<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityRolesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ClientIdentityRolesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ClientIdentityRolesAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRoles returns null on a freshly created holder.
     */
    public function testRolesNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithClientIdentityRolesAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRolesAssigned());
        $this->assertNull($holder->getRoles());
    }
}
class ImplWithClientIdentityRolesAttributeHolderUnitTest
{
    use ClientIdentityRolesAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRolesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRoles();
    }
}
